pub(crate) const PROTOCOL_VERSION: &str = "2024-11-05";
pub(crate) const TOOLS_JSON: &str = r###"[{"name":"probierz_list_surfaces","description":"List the cross-platform test surfaces (web, electron, mobile, desktop-native): tool, npm script, targets, and relevant env vars.","inputSchema":{"type":"object","properties":{},"required":[]}},{"name":"probierz_list_specs","description":"Discover e2e/spec files on disk; optional surface narrows to one (web|electron|mobile|desktop-native).","inputSchema":{"type":"object","properties":{"surface":{"type":"string","description":"Optional surface filter."}},"required":[]}},{"name":"probierz_describe_spec","description":"Static outline of a spec (describe/it/test titles in file order) by its path under the probierz root. Does not execute anything.","inputSchema":{"type":"object","properties":{"spec":{"type":"string","description":"Spec path, e.g. packages/mobile/test/specs/byk.e2e.ts"}},"required":["spec"]}},{"name":"probierz_run_command","description":"Return the exact shell command to run a target yourself (web|electron|mobile:ios|mobile:android|desktop:mac|desktop:win). Read-only: probierz never runs it.","inputSchema":{"type":"object","properties":{"target":{"type":"string","description":"One of web, electron, mobile:ios, mobile:android, desktop:mac, desktop:win."}},"required":["target"]}},{"name":"probierz_check","description":"Preflight a target's toolchain WITHOUT running anything: reports whether it is ready and, for each missing piece, exactly how to fix it -- `probierz setup <target>` for parts probierz owns (Playwright browsers, Appium drivers) or a host install command for the rest (Xcode, Android SDK, simulators, WinAppDriver). Read-only.","inputSchema":{"type":"object","properties":{"target":{"type":"string","description":"One of web, electron, mobile:ios, mobile:android, desktop:mac, desktop:win."}},"required":["target"]}},{"name":"probierz_setup","description":"Install the toolchain parts probierz owns for a target (npm deps + Playwright browsers, or npm deps + the Appium driver). Does NOT install host-level dependencies (Xcode, Android SDK, simulators, WinAppDriver) -- probierz_check reports those. Side-effecting: runs npm / appium driver install.","inputSchema":{"type":"object","properties":{"target":{"type":"string","description":"One of web, electron, mobile:ios, mobile:android, desktop:mac, desktop:win."},"timeoutMs":{"type":"number","description":"Kill a setup step after this many ms (default 30 min)."}},"required":["target"]}},{"name":"probierz_run","description":"EXECUTE a target end-to-end, capture evidence, analyze it, and dispatch a bounded Brama repair worker when it fails. Heavy + side-effecting: needs the target toolchain; noRepair=true records without repair.","inputSchema":{"type":"object","properties":{"target":{"type":"string","description":"One of web, electron, mobile:ios, mobile:android, desktop:mac, desktop:win."},"record":{"type":"boolean","description":"Force video + trace + screenshot capture on."},"appId":{"type":"string","description":"Product identifier used in the run-scoped artifact path and manifest."},"env":{"type":"object","description":"Condition env vars, e.g. { BASE_URL, APP_IOS, PROBIERZ_LOCALE, PROBIERZ_COLOR_SCHEME }."},"timeoutMs":{"type":"number","description":"Kill the run after this many ms (default 20 min)."},"resourceWaitMs":{"type":"number","description":"Wait this long for a busy device/port lease; 0 fails fast."},"frames":{"type":"number","description":"Extract this many frames per recorded video (needs ffmpeg)."},"analyze":{"type":"boolean","description":"Analyze the report after the run (default true)."},"force":{"type":"boolean","description":"Skip the preflight gate and spawn even if the toolchain looks incomplete."},"spec":{"type":"string","description":"Run only this one spec (path/substring), e.g. packages/mobile/test/specs/byk.e2e.ts, to scope the run to a single app's suite."},"noRepair":{"type":"boolean","description":"Record a failed run without dispatching Brama."}},"required":["target"]}},{"name":"probierz_analyze","description":"Parse a finished run's report (Playwright report.json or the WDIO probierz-<kind>-results.json) and inventory its media: totals, per-test status, failure reasons, and recording metadata (duration/dimensions via ffprobe, optional frame montage via ffmpeg).","inputSchema":{"type":"object","properties":{"reportPath":{"type":"string","description":"Path to the machine-readable report (from a probierz_run result)."},"artifactsDir":{"type":"string","description":"Directory to inventory for media (from a probierz_run result)."},"tool":{"type":"string","description":"playwright | wdio (inferred from the report if omitted)."},"frames":{"type":"number","description":"Extract this many frames per video (needs ffmpeg)."}},"required":["reportPath"]}},{"name":"probierz_evaluate_figure","description":"SIDE-EFFECTING: render a scientific reference/candidate pair, run deterministic geometry checks, score the declared visual rubric through the authenticated model router, and write immutable PNG evidence plus a JSON verdict.","inputSchema":{"type":"object","properties":{"referencePath":{"type":"string","description":"Reference or intermediate SVG, TeX, PDF, or raster image."},"candidatePath":{"type":"string","description":"Candidate or final SVG, TeX, PDF, or raster image."},"rubricPath":{"type":"string","description":"Optional JSON rubric; uses the scientific-figure release rubric by default."},"texPreamblePath":{"type":"string","description":"Optional LaTeX preamble lines added to the standalone wrapper used for TeX input."},"model":{"type":"string","description":"Vision-capable model ID; defaults to PROBIERZ_FIGURE_VISION_MODEL."},"agentId":{"type":"string","description":"Agent identity for subscription routes; the secret comes from PROBIERZ_MODEL_AGENT_SECRET."},"outputPath":{"type":"string","description":"Optional destination ending in .json; existing evidence is never overwritten."}},"required":["referencePath","candidatePath"]}},{"name":"probierz_evaluate_seo","description":"SIDE-EFFECTING: crawl a declared site as ordinary Chrome and Googlebot Smartphone, enforce indexability and structured-data contracts, collect mobile performance evidence, run two independent Brama content graders with conditional adjudication, ingest optional Search Console/CrUX evidence, and write an immutable signed SEO verdict.","inputSchema":{"type":"object","properties":{"appId":{"type":"string","description":"Manifest app ID; defaults to landing-page."},"baseUrl":{"type":"string","description":"Credential-free HTTPS origin or loopback HTTP URL to evaluate."},"policyPath":{"type":"string","description":"Optional SEO policy JSON; defaults to manifest seo.policy."},"briefPath":{"type":"string","description":"Optional approved landing brief JSON; defaults to manifest seo.brief."},"mode":{"type":"string","description":"pull-request, release, nightly, or production; defaults to release."},"outputPath":{"type":"string","description":"Optional immutable report destination ending in .json."},"productionEvidencePath":{"type":"string","description":"Optional Search Console and CrUX evidence JSON."},"primaryModel":{"type":"string","description":"Pinned first Brama model ID."},"secondaryModel":{"type":"string","description":"Pinned independent second Brama model ID."},"adjudicatorModel":{"type":"string","description":"Pinned Brama model used only when graders disagree."},"routerBaseUrl":{"type":"string","description":"Brama-compatible router base; defaults to STADO_MODEL_ROUTER_URL."},"agentId":{"type":"string","description":"Probierz model identity."},"privateKeyFile":{"type":"string","description":"Ed25519 PKCS#8 PEM file for release evidence signing."}},"required":["baseUrl"]}},{"name":"probierz_create_readme_gif","description":"SIDE-EFFECTING: convert one recorded journey video into a bounded, silent, looping README GIF and write a provenance sidecar with source/output SHA-256 and mandatory publication checks. Requires ffmpeg.","inputSchema":{"type":"object","properties":{"input":{"type":"string","description":"Recorded journey video path."},"output":{"type":"string","description":"Destination path ending in .gif."},"startSeconds":{"type":"number","description":"Non-negative trim offset; default 0."},"durationSeconds":{"type":"number","description":"Published clip duration; default 12, maximum 30."},"framesPerSecond":{"type":"number","description":"GIF frame rate; default 12, maximum 20."},"width":{"type":"number","description":"Output width; default 960, maximum 1200."},"force":{"type":"boolean","description":"Replace an existing GIF and sidecar."}},"required":["input","output"]}},{"name":"probierz_affected","description":"Given a change, report which run targets it could affect, so you re-run only what is relevant. Deterministic + structural (maps files to targets by package containment; agent/ or repo-root files are cross-cutting -> all targets). Provide `files` explicitly, or omit to diff the working tree against `ref` (default HEAD) via git. Read-only.","inputSchema":{"type":"object","properties":{"files":{"type":"array","items":{"type":"string"},"description":"Changed file paths (repo-relative). If given, git is not consulted."},"ref":{"type":"string","description":"git ref to diff the working tree against when `files` is omitted (default HEAD)."}},"required":[]}},{"name":"probierz_ci","description":"Change-driven pass: select affected targets, run and analyze them, then dispatch a bounded Brama repair worker for each failure unless noRepair=true. Selection and blockers stay deterministic; only the explicit repair step asks a model what to change.","inputSchema":{"type":"object","properties":{"files":{"type":"array","items":{"type":"string"},"description":"Changed file paths (repo-relative). If given, git is not consulted."},"ref":{"type":"string","description":"git ref to diff the working tree against when `files` is omitted (default HEAD)."},"appId":{"type":"string","description":"Product identifier for every selected run."},"env":{"type":"object","description":"Conditions forwarded to every selected run."},"spec":{"type":"string","description":"Optional spec filter forwarded to every selected target."},"record":{"type":"boolean","description":"Force video/trace/screenshot capture on for every run."},"force":{"type":"boolean","description":"Skip each target's preflight gate and spawn anyway."},"frames":{"type":"number","description":"Extract this many frames per recorded video (needs ffmpeg)."},"timeoutMs":{"type":"number","description":"Per-run timeout in ms."},"resourceWaitMs":{"type":"number","description":"Wait per selected run for a busy device/port lease; default 10 min, 0 fails fast."},"noRepair":{"type":"boolean","description":"Record failed runs without dispatching Brama."}},"required":[]}},{"name":"probierz_history","description":"Read deterministic E5 stability history: pass rate, infrastructure failures, duration trend, flaky tests, journeys, latest run, and last green.","inputSchema":{"type":"object","properties":{"appId":{"type":"string","description":"Product identifier (default probierz)."},"target":{"type":"string","description":"Optional target filter."},"limit":{"type":"number","description":"Maximum recent runs (default 50)."}},"required":[]}},{"name":"probierz_dashboard","description":"Project evidence for product → version → journey → surface → device → result → artifact dashboard navigation.","inputSchema":{"type":"object","properties":{"appId":{"type":"string"},"limit":{"type":"number","description":"Maximum recent runs (default 500)."}},"required":["appId"]}},{"name":"probierz_matrix_plan","description":"Read the deterministic nightly or release matrix without executing it.","inputSchema":{"type":"object","properties":{"appId":{"type":"string"},"profile":{"type":"string","description":"nightly or release"}},"required":["appId","profile"]}},{"name":"probierz_run_matrix","description":"HEAVY + SIDE-EFFECTING: execute every cell of a declared nightly or release matrix and return an E4 verdict.","inputSchema":{"type":"object","properties":{"appId":{"type":"string"},"profile":{"type":"string","description":"nightly or release"},"release":{"type":"string","description":"Required for a release matrix."},"env":{"type":"object","description":"Secrets and exact release artifact conditions; matrix axes cannot be overridden."}},"required":["appId","profile"]}},{"name":"probierz_protect_run","description":"SIDE-EFFECTING: encrypt a complete run into an authenticated AES-256-GCM evidence bundle; optionally remove plaintext artifacts.","inputSchema":{"type":"object","properties":{"appId":{"type":"string"},"runId":{"type":"string"},"kind":{"type":"string"},"keyFile":{"type":"string"},"removePlaintext":{"type":"boolean"}},"required":["appId","runId"]}},{"name":"probierz_restore_bundle","description":"SIDE-EFFECTING: authenticate and restore an encrypted evidence bundle into an empty directory.","inputSchema":{"type":"object","properties":{"file":{"type":"string"},"destination":{"type":"string"},"keyFile":{"type":"string"}},"required":["file","destination"]}},{"name":"probierz_retention","description":"Plan retention expiry; with apply=true, delete expired plaintext runs and encrypted bundles.","inputSchema":{"type":"object","properties":{"appId":{"type":"string"},"at":{"type":"string","description":"Optional ISO timestamp."},"apply":{"type":"boolean"}},"required":["appId"]}},{"name":"probierz_secret_scan","description":"Scan a plaintext artifact directory for high-confidence secrets without returning secret values.","inputSchema":{"type":"object","properties":{"directory":{"type":"string"}},"required":["directory"]}},{"name":"probierz_audit","description":"Read and integrity-check access audit records, optionally filtered by app, run, or action.","inputSchema":{"type":"object","properties":{"appId":{"type":"string"},"runId":{"type":"string"},"action":{"type":"string"},"limit":{"type":"number"}},"required":[]}},{"name":"probierz_source_identity","description":"Compute exact path-independent harness and app source SHA-256 identities.","inputSchema":{"type":"object","properties":{"appId":{"type":"string"}},"required":["appId"]}},{"name":"probierz_gate_status","description":"Read pull-request and release gate activation state.","inputSchema":{"type":"object","properties":{"appId":{"type":"string"}},"required":["appId"]}},{"name":"probierz_status","description":"Journey coverage, evidence freshness vs HEAD, untested surfaces, and pull-request merge eligibility for an app.","inputSchema":{"type":"object","properties":{"appId":{"type":"string"},"baseRef":{"type":"string","description":"Default origin/main."}},"required":["appId"]}},{"name":"probierz_gate_prepush","description":"Pre-push merge gate: select affected journeys from the push diff and evaluate the newest passing runs against the exact current HEAD identity (pull-request policy).","inputSchema":{"type":"object","properties":{"repo":{"type":"string"},"appId":{"type":"string","description":"Inferred from manifest repositories when omitted."},"base":{"type":"string"},"head":{"type":"string"},"runCi":{"type":"boolean","description":"Run probierz ci <base> before evaluating."}},"required":["repo"]}},{"name":"probierz_author_spec","description":"SIDE-EFFECTING: use the authenticated Stado model router to draft one journey spec from a probe of the real app, verify it with an actual run, and keep it on green (registers the journey in the app manifest).","inputSchema":{"type":"object","properties":{"appId":{"type":"string"},"journey":{"type":"string"},"target":{"type":"string","description":"web|electron|mobile:ios|mobile:android|desktop:mac|desktop:win|tui"},"desc":{"type":"string","description":"Journey goal in one or two sentences."},"baseUrl":{"type":"string"},"appPath":{"type":"string"},"rounds":{"type":"number"}},"required":["appId","journey","target","desc"]}},{"name":"probierz_repair","description":"SIDE-EFFECTING: dispatch one bounded Brama worker at a recorded failed run. Product fixes land on a fresh published branch; spec fixes must pass the real journey before publication.","inputSchema":{"type":"object","properties":{"appId":{"type":"string"},"runId":{"type":"string"},"rounds":{"type":"number","description":"One to three bounded repair rounds."},"dryRun":{"type":"boolean","description":"Write the decision brief but do not call Brama or change repositories."}},"required":["appId"]}},{"name":"probierz_author_manifest","description":"SIDE-EFFECTING: use the authenticated Stado model router to draft the whole app journey manifest from a probe and repository layout, validate it, and optionally cover every journey with author-spec.","inputSchema":{"type":"object","properties":{"appId":{"type":"string"},"desc":{"type":"string","description":"What the app does, in one or two sentences."},"repositories":{"type":"array","items":{"type":"string"}},"target":{"type":"string"},"baseUrl":{"type":"string"},"appPath":{"type":"string"},"withSpecs":{"type":"boolean"}},"required":["appId","desc","repositories","target"]}},{"name":"probierz_stado_run","description":"SIDE-EFFECTING: run a target on a chosen stado host (provider/pin/spot/GPU); evidence lands back in test-results.","inputSchema":{"type":"object","properties":{"target":{"type":"string"},"appId":{"type":"string"},"spec":{"type":"string"},"host":{"type":"string","description":"stado:gcp|azure|aws|any|spot|local|t4"},"cargoRelease":{"type":"boolean","description":"Build the app binary on the worker with cargo (needs appRepo)."},"appRepo":{"type":"string"},"watch":{"type":"boolean","description":"Default true; waits for completion and fetches results."}},"required":["target","appId"]}},{"name":"probierz_stado_evaluate_seo","description":"SIDE-EFFECTING: submit the complete SEO evaluator to a Stado-selected dedicated host, materialize only the declared Brama and signing secrets, and fetch the immutable evidence bundle.","inputSchema":{"type":"object","properties":{"appId":{"type":"string","description":"Manifest app ID; defaults to landing-page."},"baseUrl":{"type":"string"},"mode":{"type":"string","description":"pull-request, release, nightly, or production."},"policyPath":{"type":"string"},"briefPath":{"type":"string"},"primaryModel":{"type":"string"},"secondaryModel":{"type":"string"},"adjudicatorModel":{"type":"string"},"agentId":{"type":"string"},"productionEvidencePath":{"type":"string"},"host":{"type":"string","description":"Dedicated Stado host; defaults to stado:mini."},"watch":{"type":"boolean","description":"Default true; waits for completion and fetches results."}},"required":["baseUrl","primaryModel","secondaryModel","adjudicatorModel"]}},{"name":"probierz_gate_evaluate","description":"Evaluate exact build, E3 evidence, coverage, matrix, encryption, secret scan, and signed receipt eligibility; appends an audit record.","inputSchema":{"type":"object","properties":{"appId":{"type":"string"},"mode":{"type":"string","description":"pull-request or release"},"expectedHarnessSha":{"type":"string"},"expectedSourceSha":{"type":"string"},"runIds":{"type":"array","items":{"type":"string"}},"release":{"type":"string","description":"Required for release mode."},"receiptFile":{"type":"string","description":"Required signed evidence receipt for release mode."},"trustedPublicKeyFile":{"type":"string"},"expectedFingerprint":{"type":"string"}},"required":["appId","mode","expectedHarnessSha","expectedSourceSha","runIds"]}},{"name":"probierz_gate_enforce","description":"Enforce an activated gate against current evidence; pending-green gates fail closed.","inputSchema":{"type":"object","properties":{"appId":{"type":"string"},"mode":{"type":"string","description":"pull-request or release"},"expectedHarnessSha":{"type":"string"},"expectedSourceSha":{"type":"string"},"runIds":{"type":"array","items":{"type":"string"}},"release":{"type":"string","description":"Required for release mode."},"receiptFile":{"type":"string","description":"Required signed evidence receipt for release mode."},"trustedPublicKeyFile":{"type":"string"},"expectedFingerprint":{"type":"string"}},"required":["appId","mode","expectedHarnessSha","expectedSourceSha","runIds"]}},{"name":"probierz_gate_activate","description":"SIDE-EFFECTING: atomically activate a gate only after all green evidence requirements pass.","inputSchema":{"type":"object","properties":{"appId":{"type":"string"},"mode":{"type":"string","description":"pull-request or release"},"expectedHarnessSha":{"type":"string"},"expectedSourceSha":{"type":"string"},"runIds":{"type":"array","items":{"type":"string"}},"release":{"type":"string","description":"Required for release mode."},"receiptFile":{"type":"string","description":"Required signed evidence receipt for release mode."},"trustedPublicKeyFile":{"type":"string"},"expectedFingerprint":{"type":"string"}},"required":["appId","mode","expectedHarnessSha","expectedSourceSha","runIds"]}},{"name":"probierz_compare_runs","description":"Deterministically compare status, duration, tests, evidence, build identity, and artifact hashes between two run IDs.","inputSchema":{"type":"object","properties":{"appId":{"type":"string","description":"Product identifier (default probierz)."},"leftRunId":{"type":"string"},"rightRunId":{"type":"string"}},"required":["leftRunId","rightRunId"]}},{"name":"probierz_last_green","description":"Return the newest passing run for a product, optional target, and optional journey.","inputSchema":{"type":"object","properties":{"appId":{"type":"string","description":"Product identifier (default probierz)."},"target":{"type":"string"},"journey":{"type":"string"}},"required":[]}},{"name":"probierz_create_receipt","description":"SIDE-EFFECTING: secret-scan evidence, verify exact source/build/artifact provenance, and sign a release receipt with immutable journey identities and report-typed publication media.","inputSchema":{"type":"object","properties":{"appId":{"type":"string"},"release":{"type":"string"},"expectedHarnessSha":{"type":"string"},"expectedSourceSha":{"type":"string"},"runIds":{"type":"array","items":{"type":"string"}},"requiredJourneys":{"type":"array","items":{"type":"string"}},"minimumEvidence":{"type":"string","description":"Default E3."},"privateKeyFile":{"type":"string","description":"Defaults to PROBIERZ_RECEIPT_PRIVATE_KEY_FILE."}},"required":["appId","release","expectedHarnessSha","expectedSourceSha","runIds"]}},{"name":"probierz_verify_receipt","description":"Verify receipt payload hash and Ed25519 signature against an explicit trusted public key or fingerprint.","inputSchema":{"type":"object","properties":{"file":{"type":"string"},"trustedPublicKeyFile":{"type":"string"},"expectedFingerprint":{"type":"string"}},"required":["file"]}},{"name":"probierz_create_publication_manifest","description":"SIDE-EFFECTING: verify a signed receipt, current source, secret scan, evidence hashes, driver capability, redaction review, and immutable storage registrations before emitting a deterministic first-use publication manifest.","inputSchema":{"type":"object","properties":{"receiptFile":{"type":"string"},"attemptId":{"type":"string"},"journeyId":{"type":"string"},"assets":{"type":"array","items":{"type":"object","properties":{"file":{"type":"string"},"kind":{"type":"string","enum":["screenshot","recording","trace"]},"storageUrl":{"type":"string"},"contentSha256":{"type":"string"},"redactionStatus":{"type":"string","enum":["verified_redacted","not_applicable"]},"verifiedAt":{"type":"string"}},"required":["file","storageUrl","contentSha256","redactionStatus","verifiedAt"],"additionalProperties":false}},"trustedPublicKeyFile":{"type":"string"},"expectedFingerprint":{"type":"string"}},"required":["receiptFile","attemptId","journeyId","assets"]}},{"name":"probierz_start_run","description":"HEAVY + SIDE-EFFECTING: start a real run asynchronously and return its runId immediately. Poll with probierz_run_status; cancel with probierz_cancel_run.","inputSchema":{"type":"object","properties":{"target":{"type":"string"},"record":{"type":"boolean"},"appId":{"type":"string"},"env":{"type":"object"},"timeoutMs":{"type":"number"},"resourceWaitMs":{"type":"number","description":"Wait this long for a busy device/port lease; 0 fails fast."},"frames":{"type":"number"},"analyze":{"type":"boolean"},"force":{"type":"boolean"},"spec":{"type":"string"},"noRepair":{"type":"boolean","description":"Record a failed run without dispatching Brama."}},"required":["target"]}},{"name":"probierz_run_status","description":"Return queued/running/blocked/passed/failed/canceled state for an asynchronous run.","inputSchema":{"type":"object","properties":{"runId":{"type":"string"}},"required":["runId"]}},{"name":"probierz_cancel_run","description":"Cancel an asynchronous run and terminate its complete spawned process tree.","inputSchema":{"type":"object","properties":{"runId":{"type":"string"}},"required":["runId"]}},{"name":"probierz_get_result","description":"Return the completed normalized result and evidence for an asynchronous run.","inputSchema":{"type":"object","properties":{"runId":{"type":"string"}},"required":["runId"]}},{"name":"probierz_list_artifacts","description":"List run-scoped evidence artifacts for a completed asynchronous run.","inputSchema":{"type":"object","properties":{"runId":{"type":"string"}},"required":["runId"]}},{"name":"probierz_get_artifact","description":"Read one run-scoped artifact up to 5 MiB as base64; path traversal is rejected.","inputSchema":{"type":"object","properties":{"runId":{"type":"string"},"file":{"type":"string","description":"Run-relative artifact path."}},"required":["runId","file"]}}]"###;

pub(crate) const MAX_ARTIFACT_BYTES: u64 = 5 * 1024 * 1024;

